        let result = obj; for (const key of keys) { if (result === null || result === undefined) return defaultValue; result = result[key]; }
        return result === undefined ? defaultValue : result;
    }
    function extractVal(rawValue, defaultValue = '--') {
        if (rawValue === undefined || rawValue === null) return defaultValue;
        const valueToProcess = Array.isArray(rawValue) && rawValue.length > 0 ? rawValue[0] : rawValue;
        return String(valueToProcess);
    }
    function updateField(id, value, isEmojiPrepended = false) {
        const el = document.getElementById(id);
        if (el) { if (isEmojiPrepended) { el.innerHTML = value; } else { el.innerText = value; } }
