            valueDisp.innerText = String(numericValue);
            const clampedValue = Math.max(min, Math.min(max, numericValue));
            const percentage = max === min ? 0 : ((clampedValue - min) / (max - min)) * 100;
            bar.style.width = `${percentage}%`;
